PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "users_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "users_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_hashtag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "videos_count" integer unsigned NOT NULL CHECK ("videos_count" >= 0));
CREATE TABLE IF NOT EXISTS "videos_follower" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "follower_user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(50) NOT NULL, "message" text NOT NULL, "read_status" bool NOT NULL, "created_at" datetime NOT NULL, "user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_videohashtag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "hashtag_id_id" bigint NOT NULL REFERENCES "videos_hashtag" ("id") DEFERRABLE INITIALLY DEFERRED, "video_id_id" bigint NOT NULL REFERENCES "videos_video" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "slug" varchar(50) NULL UNIQUE, "description" text NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "image" varchar(100) NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "seo_title" varchar(255) NULL, "seo_description" text NULL, "parent_id" bigint NULL REFERENCES "videos_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "markerplace_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "description" text NULL);
CREATE TABLE IF NOT EXISTS "markerplace_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "description" text NULL, "price" decimal NOT NULL, "stock" integer unsigned NOT NULL CHECK ("stock" >= 0), "image" varchar(100) NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "status" varchar(20) NOT NULL, "category_id" bigint NULL REFERENCES "markerplace_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "wallet_currencymodel" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(5) NOT NULL UNIQUE, "name" varchar(50) NOT NULL, "symbol" varchar(5) NOT NULL, "type" varchar(10) NOT NULL, "decimals" integer NOT NULL, "exchange_rate_to_usd" decimal NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "users_country" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "code" varchar(10) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "videos_like" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "video_id_id" bigint NOT NULL REFERENCES "videos_video" ("id") DEFERRABLE INITIALLY DEFERRED, "uuid" varchar(32) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "videos_view" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "video_id_id" bigint NOT NULL REFERENCES "videos_video" ("id") DEFERRABLE INITIALLY DEFERRED, "uuid" varchar(32) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "videos_story" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" varchar(32) NOT NULL UNIQUE, "text" text NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_storyview" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "viewed_at" datetime NOT NULL, "story_id" bigint NOT NULL REFERENCES "videos_story" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_storymedia" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "file" varchar(100) NOT NULL, "type" varchar(20) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "story_id" bigint NOT NULL REFERENCES "videos_story" ("id") DEFERRABLE INITIALLY DEFERRED, "uuid" varchar(32) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "videos_storylike" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "liked_at" datetime NOT NULL, "story_id" bigint NOT NULL REFERENCES "videos_story" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_giftstory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "video" varchar(100) NOT NULL, "token_price" integer unsigned NOT NULL CHECK ("token_price" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "emoji" varchar(100) NULL, "color_premiun" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "videos_storygift" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "created_at" datetime NOT NULL, "gift_id" bigint NOT NULL REFERENCES "videos_giftstory" ("id") DEFERRABLE INITIALLY DEFERRED, "sender_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "story_id" bigint NOT NULL REFERENCES "videos_story" ("id") DEFERRABLE INITIALLY DEFERRED, "gift_type" varchar(20) NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "uuid" varchar(32) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "videos_chatroom" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" varchar(8) NOT NULL UNIQUE, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "last_message_preview" varchar(255) NULL, "last_message_time" datetime NULL, "unread_count_p1" integer unsigned NOT NULL CHECK ("unread_count_p1" >= 0), "unread_count_p2" integer unsigned NOT NULL CHECK ("unread_count_p2" >= 0), "participant1_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "participant2_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "initiator_id" bigint NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_message" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" varchar(8) NOT NULL UNIQUE, "content" text NOT NULL, "message_type" varchar(20) NOT NULL, "file" varchar(100) NULL, "is_deleted" bool NOT NULL, "deleted_for_all" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "chat_room_id" bigint NOT NULL REFERENCES "videos_chatroom" ("id") DEFERRABLE INITIALLY DEFERRED, "sender_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_useronlinestatus" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_online" bool NOT NULL, "last_seen" datetime NOT NULL, "last_activity" datetime NOT NULL, "device_token" varchar(255) NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_typingstatus" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_typing" bool NOT NULL, "updated_at" datetime NOT NULL, "chat_room_id" bigint NOT NULL REFERENCES "videos_chatroom" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_messagereaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "reaction" varchar(10) NOT NULL, "created_at" datetime NOT NULL, "message_id" bigint NOT NULL REFERENCES "videos_message" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "token_blacklist_blacklistedtoken" ("blacklisted_at" datetime NOT NULL, "token_id" bigint NOT NULL UNIQUE REFERENCES "token_blacklist_outstandingtoken" ("id") DEFERRABLE INITIALLY DEFERRED, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT);
CREATE TABLE IF NOT EXISTS "token_blacklist_outstandingtoken" ("token" text NOT NULL, "created_at" datetime NULL, "expires_at" datetime NOT NULL, "user_id" bigint NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "jti" varchar(255) NOT NULL UNIQUE, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT);
CREATE TABLE IF NOT EXISTS "users_trending" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "term" varchar(255) NOT NULL UNIQUE, "count" integer unsigned NOT NULL CHECK ("count" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "users_recentsearch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "term" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "wallet_walletmodel" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "balance" decimal NOT NULL, "pass_code" varchar(18) NOT NULL UNIQUE, "wallet_type" varchar(10) NOT NULL, "bonus_balance" decimal NOT NULL, "blocked_amount" decimal NOT NULL, "total_deposited" decimal NOT NULL, "total_withdrawn" decimal NOT NULL, "last_transaction_at" datetime NULL, "is_active" bool NOT NULL, "version" integer NOT NULL, "created_at" datetime NULL, "updated_at" datetime NULL, "currency_id" bigint NULL REFERENCES "wallet_currencymodel" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "tokens" integer unsigned NOT NULL CHECK ("tokens" >= 0));
CREATE TABLE IF NOT EXISTS "subscriptions_subscriptionplan" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(20) NOT NULL UNIQUE, "description" text NULL, "price" decimal NOT NULL, "stripe_price_id" varchar(100) NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "wallet_transactionmodel" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transaction_type" varchar(10) NOT NULL, "amount" decimal NOT NULL, "description" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "wallet_id" bigint NOT NULL REFERENCES "wallet_walletmodel" ("id") DEFERRABLE INITIALLY DEFERRED, "payment_id" varchar(255) NULL, "status" varchar(10) NOT NULL, "bank_account_id" bigint NULL REFERENCES "wallet_bankaccount" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "users_availability" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "day_of_week" smallint unsigned NOT NULL CHECK ("day_of_week" >= 0), "start_time" time NOT NULL, "end_time" time NOT NULL, "is_active" bool NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "users_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "platform" varchar(20) NOT NULL, "platform_user_id" varchar(255) NOT NULL, "platform_username" varchar(255) NOT NULL, "access_token" text NOT NULL, "refresh_token" text NOT NULL, "connected_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "followers_count" integer unsigned NOT NULL CHECK ("followers_count" >= 0));
CREATE TABLE IF NOT EXISTS "videos_videogift" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" varchar(32) NOT NULL UNIQUE, "gift_type" varchar(20) NOT NULL, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "created_at" datetime NOT NULL, "is_active" bool NOT NULL, "gift_id" bigint NOT NULL REFERENCES "videos_giftstory" ("id") DEFERRABLE INITIALLY DEFERRED, "sender_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "video_id" bigint NOT NULL REFERENCES "videos_video" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "subscriptions_subscriptionbenefit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "benefit_type" varchar(20) NOT NULL, "limit" integer unsigned NOT NULL CHECK ("limit" >= 0), "description" varchar(255) NULL, "plan_id" bigint NOT NULL REFERENCES "subscriptions_subscriptionplan" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "wallet_tokenpackage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tokens" integer unsigned NOT NULL CHECK ("tokens" >= 0), "price" decimal NOT NULL, "is_active" bool NOT NULL, "is_popular" bool NOT NULL, "color_gradient" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "wallet_globalsettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "custom_token_price_usd" decimal NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "wallet_bankaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "account_holder_name" varchar(255) NOT NULL, "bank_name" varchar(255) NOT NULL, "encrypted_account_number" text NOT NULL, "encrypted_routing_number" text NULL, "is_primary" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "stripe_account_id" varchar(255) NULL, "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "ads_adcampaign" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "objective" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "start_date" datetime NULL, "end_date" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "ads_adcreative" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "description" text NOT NULL, "media_file" varchar(100) NOT NULL, "cta_text" varchar(20) NOT NULL, "destination_url" varchar(200) NOT NULL, "campaign_id" bigint NOT NULL UNIQUE REFERENCES "ads_adcampaign" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "ads_adanalytics" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "impressions" integer unsigned NOT NULL CHECK ("impressions" >= 0), "clicks" integer unsigned NOT NULL CHECK ("clicks" >= 0), "conversions" integer unsigned NOT NULL CHECK ("conversions" >= 0), "date" date NOT NULL, "campaign_id" bigint NOT NULL REFERENCES "ads_adcampaign" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "ads_adimpression" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "timestamp" datetime NOT NULL, "campaign_id" bigint NOT NULL REFERENCES "ads_adcampaign" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "ads_adbudget" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "daily_budget" decimal NOT NULL, "total_budget" decimal NOT NULL, "campaign_id" bigint NOT NULL UNIQUE REFERENCES "ads_adcampaign" ("id") DEFERRABLE INITIALLY DEFERRED, "spent_amount" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "videos_aistyle" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "slug" varchar(50) NOT NULL UNIQUE, "description" text NULL, "icon_name" varchar(50) NOT NULL, "color_bg" varchar(100) NOT NULL, "color_text" varchar(100) NOT NULL, "color_border" varchar(100) NOT NULL, "is_active" bool NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "videos_aitemplate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(100) NOT NULL, "prompt" text NOT NULL, "image_url" varchar(200) NULL, "media_type" varchar(20) NOT NULL, "is_active" bool NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "created_at" datetime NOT NULL, "style_id" bigint NOT NULL REFERENCES "videos_aistyle" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_aigenerationhistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "prompt" text NOT NULL, "media_url" varchar(500) NOT NULL, "media_type" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "style_id" bigint NULL REFERENCES "videos_aistyle" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "videos_video" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" varchar(32) NOT NULL UNIQUE, "video_url" varchar(200) NOT NULL, "video" varchar(100) NULL, "thumbnail_url" varchar(200) NOT NULL, "description" text NULL, "tags" text NOT NULL CHECK ((JSON_VALID("tags") OR "tags" IS NULL)), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "duration" integer unsigned NOT NULL CHECK ("duration" >= 0), "category_id" bigint NULL REFERENCES "videos_category" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "media_type" varchar(10) NOT NULL);
CREATE TABLE IF NOT EXISTS "ads_adaudience" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "age_min" integer unsigned NOT NULL CHECK ("age_min" >= 0), "age_max" integer unsigned NOT NULL CHECK ("age_max" >= 0), "gender" varchar(10) NOT NULL, "locations" text NOT NULL CHECK ((JSON_VALID("locations") OR "locations" IS NULL)), "interests" text NOT NULL CHECK ((JSON_VALID("interests") OR "interests" IS NULL)), "estimated_reach" integer unsigned NOT NULL CHECK ("estimated_reach" >= 0), "campaign_id" bigint NOT NULL UNIQUE REFERENCES "ads_adcampaign" ("id") DEFERRABLE INITIALLY DEFERRED, "latitude" real NULL, "longitude" real NULL, "radius" integer unsigned NOT NULL CHECK ("radius" >= 0));
CREATE TABLE IF NOT EXISTS "videos_videostats" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "starts" integer unsigned NOT NULL CHECK ("starts" >= 0), "engagements" integer unsigned NOT NULL CHECK ("engagements" >= 0), "valid_views" integer unsigned NOT NULL CHECK ("valid_views" >= 0), "updated_at" datetime NOT NULL, "video_id" bigint NOT NULL UNIQUE REFERENCES "videos_video" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "users_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(30) NOT NULL, "last_name" varchar(30) NOT NULL, "birthdate" date NULL, "profile_picture" varchar(100) NULL, "bio" text NULL, "is_active" bool NOT NULL, "is_staff" bool NOT NULL, "country_id" bigint NULL REFERENCES "users_country" ("id") DEFERRABLE INITIALLY DEFERRED, "is_phone_verified" bool NOT NULL, "phone_number" varchar(20) NULL, "reset_password_code" varchar(6) NULL, "reset_password_expires" datetime NULL, "profile_video" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "videos_comment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" varchar(32) NULL UNIQUE, "content" text NOT NULL, "created_at" datetime NOT NULL, "user_id_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "video_id_id" bigint NOT NULL REFERENCES "videos_video" ("id") DEFERRABLE INITIALLY DEFERRED, "is_priority_comment" bool NOT NULL, "parent_id" bigint NULL REFERENCES "videos_comment" ("id") DEFERRABLE INITIALLY DEFERRED, "priority_plan_name" varchar(20) NULL);
CREATE TABLE IF NOT EXISTS "subscriptions_usersubscription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "stripe_subscription_id" varchar(100) NULL, "stripe_customer_id" varchar(100) NULL, "start_date" datetime NOT NULL, "end_date" datetime NULL, "is_active" bool NOT NULL, "comments_this_month" integer unsigned NOT NULL CHECK ("comments_this_month" >= 0), "calls_this_month" integer unsigned NOT NULL CHECK ("calls_this_month" >= 0), "plan_id" bigint NULL REFERENCES "subscriptions_subscriptionplan" ("id") DEFERRABLE INITIALLY DEFERRED, "last_reset_date" date NOT NULL, "subscribed_to_id" bigint NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "subscriber_id" bigint NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "ai_generations_this_month" integer unsigned NOT NULL CHECK ("ai_generations_this_month" >= 0), "video_calls_this_month" integer unsigned NOT NULL CHECK ("video_calls_this_month" >= 0), "video_seconds_consumed_this_month" integer unsigned NOT NULL CHECK ("video_seconds_consumed_this_month" >= 0), "voice_seconds_this_month" integer unsigned NOT NULL CHECK ("voice_seconds_this_month" >= 0));
CREATE TABLE IF NOT EXISTS "subscriptions_callsession" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" char(32) NOT NULL UNIQUE, "call_type" varchar(10) NOT NULL, "channel_name" varchar(255) NOT NULL UNIQUE, "agora_uid_caller" integer unsigned NOT NULL CHECK ("agora_uid_caller" >= 0), "agora_uid_callee" integer unsigned NOT NULL CHECK ("agora_uid_callee" >= 0), "allowed_seconds" integer unsigned NOT NULL CHECK ("allowed_seconds" >= 0), "consumed_seconds" integer unsigned NOT NULL CHECK ("consumed_seconds" >= 0), "started_at" datetime NOT NULL, "answered_at" datetime NULL, "ended_at" datetime NULL, "status" varchar(20) NOT NULL, "ended_reason" varchar(50) NULL, "agora_token_expire_at" datetime NULL, "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "callee_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "caller_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "subscription_id" bigint NOT NULL REFERENCES "subscriptions_usersubscription" ("id") DEFERRABLE INITIALLY DEFERRED);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
